      "keystrokes": "bash -lc \"cat > main.cpp << 'CPP'\n#include <bits/stdc++.h>\nusing namespace std;\n\nstatic int n;\nstatic string s;\nstatic long long A[105];\nstatic long long dp[105][105][105];\nstatic bool vis[105][105][105];\n\nlong long solve(int l, int r, int k){\n    if(l>r) return 0;\n    if(vis[l][r][k]) return dp[l][r][k];\n    vis[l][r][k] = true;\n    long long res = solve(l, r-1, 0) + A[k+1];\n    for(int i=l; i<r; ++i){\n        if(s[i]==s[r]){\n            long long val = solve(l, i, k+1) + solve(i+1, r-1, 0);\n            if(val > res) res = val;\n        }\n    }\n    dp[l][r][k] = res;\n    return res;\n}\n\nint main(){\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    if(!(cin >> n)) return 0;\n    cin >> s;\n    for(int i=1; i<=n; ++i) cin >> A[i];\n    memset(vis, 0, sizeof(vis));\n    cout << solve(0, n-1, 0) << \"\\\\n\";\n    return 0;\n}\nCPP\" \n"
